import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';
import { setTimeout as delay } from 'node:timers/promises';

const url = process.argv[2];
const outPrefix = process.argv[3] || '/tmp/garden';
const port = 9333 + Math.floor(Math.random() * 200);

const chrome = spawn('chromium', [
  '--headless=new', '--no-sandbox', '--disable-gpu',
  '--enable-unsafe-swiftshader', '--hide-scrollbars',
  '--window-size=1440,900',
  `--remote-debugging-port=${port}`,
  '--remote-allow-origins=*',
  'about:blank'
], { stdio: ['ignore', 'ignore', 'pipe'] });

let chromeErr = '';
chrome.stderr.on('data', d => { chromeErr += d; });

async function retry(fn, ms = 500, total = 20000) {
  const t0 = Date.now();
  for (;;) {
    try { return await fn(); } catch (e) {
      if (Date.now() - t0 > total) throw e;
      await delay(ms);
    }
  }
}

const version = await retry(async () => {
  const r = await fetch(`http://127.0.0.1:${port}/json/version`);
  return r.json();
}, 300, 25000);

const ws = new WebSocket(version.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });

let msgId = 0;
const pending = new Map();
const events = [];
ws.onmessage = (ev) => {
  const m = JSON.parse(ev.data);
  if (m.id && pending.has(m.id)) {
    const { res, rej } = pending.get(m.id);
    pending.delete(m.id);
    if (m.error) rej(new Error(JSON.stringify(m.error))); else res(m.result);
  } else if (m.method) events.push(m);
};

function send(method, params = {}) {
  const id = ++msgId;
  ws.send(JSON.stringify({ id, method, params }));
  return new Promise((res, rej) => pending.set(id, { res, rej }));
}

const { targetId } = await send('Target.createTarget', { url: 'about:blank' });
const { sessionId } = await send('Target.attachToTarget', { targetId, flatten: true });

function ssend(method, params = {}) {
  const id = ++msgId;
  ws.send(JSON.stringify({ id, method, params, sessionId }));
  return new Promise((res, rej) => pending.set(id, { res, rej }));
}

await ssend('Page.enable');
await ssend('Runtime.enable');
await ssend('Log.enable');
await ssend('Network.enable');
await ssend('Emulation.setDeviceMetricsOverride', {
  width: 1440, height: 900, deviceScaleFactor: 1, mobile: false
});

const consoleMsgs = [];
const failedReqs = [];
ws.addEventListener('message', (ev) => {
  const m = JSON.parse(ev.data);
  if (m.method === 'Runtime.consoleAPICalled' && m.params) {
    consoleMsgs.push({ type: m.params.type, args: m.params.args.map(a => a.value ?? a.description ?? JSON.stringify(a.preview ?? '')) });
  }
  if (m.method === 'Runtime.exceptionThrown' && m.params) {
    consoleMsgs.push({ type: 'exception', args: [JSON.stringify(m.params.exceptionDetails)] });
  }
  if (m.method === 'Log.entryAdded' && m.params && ['error', 'warning'].includes(m.params.entry.level)) {
    consoleMsgs.push({ type: 'log:' + m.params.entry.level, args: [m.params.entry.text] });
  }
  if (m.method === 'Network.loadingFailed' && m.params) {
    failedReqs.push(m.params);
  }
});

await ssend('Page.navigate', { url });
await delay(1000);

const waitFor = (expr, timeout = 20000, poll = 400) => retry(async () => {
  const r = await ssend('Runtime.evaluate', { expression: expr, returnByValue: true });
  if (!r.result.value) throw new Error('not ready: ' + expr);
  return r.result.value;
}, poll, timeout);

const ready = await waitFor('window.__gardenReady === true', 30000).catch(() => null);
await delay(2500);

async function shot(name) {
  const r = await ssend('Page.captureScreenshot', { format: 'png' });
  writeFileSync(`${outPrefix}-${name}.png`, Buffer.from(r.data, 'base64'));
  return `${outPrefix}-${name}.png`;
}

await shot('day');

const timeNow = await ssend('Runtime.evaluate', { expression: 'window.__garden ? window.__garden.time() : null', returnByValue: true });

await ssend('Runtime.evaluate', { expression: 'window.__garden && window.__garden.setTime(22.2); window.__garden && window.__garden.setAuto(false);' });
await delay(2500);
await shot('night');

await ssend('Runtime.evaluate', { expression: 'window.__garden && window.__garden.setTime(6.8);' });
await delay(2000);
await shot('dawn');

await ssend('Runtime.evaluate', { expression: 'window.__garden && window.__garden.setTime(12.5); window.__garden && window.__garden.setAuto(true);' });
await delay(1500);

await ssend('Input.dispatchMouseEvent', { type: 'mousePressed', x: 720, y: 420, button: 'left', buttons: 1, clickCount: 1 });
for (let i = 1; i <= 12; i++) {
  await ssend('Input.dispatchMouseEvent', { type: 'mouseMoved', x: 720 + i * 18, y: 420 + i * 6, button: 'left', buttons: 1 });
  await delay(30);
}
await ssend('Input.dispatchMouseEvent', { type: 'mouseReleased', x: 936, y: 492, button: 'left', buttons: 1, clickCount: 1 });
await delay(1200);
await shot('dragged');

const state = await ssend('Runtime.evaluate', {
  expression: 'window.__garden ? window.__garden.state() : null', returnByValue: true
});

console.log(JSON.stringify({
  ready,
  time: timeNow.result && timeNow.result.value,
  state: state.result && state.result.value,
  consoleMsgs: consoleMsgs.slice(0, 40),
  failedReqs: failedReqs.slice(0, 10),
  chromeErrTail: chromeErr.slice(-500)
}, null, 2));

ws.close();
chrome.kill('SIGKILL');

