Trees:

```js
function cherry(cx, cz, seed, scale = 1) {
  const rng = mulberry32(seed);
  const th = Math.round((3.2 + rng() * 1.4) * scale);
  let x = cx, z = cz;
  for (let i = 0; i < th; i++) {
    x = cx + Math.round(Math.sin(i * 0.9 + seed) * 0.3);
    z = cz + Math.round(Math.cos(i * 0.7 + seed) * 0.3);
    voxel(x, i + 0.5, z, C.bark[i % 2]);
  }
  // branches
  const nb = 2 + Math.floor(rng() * 2);
  const tips = [[x, th, z]];
  for (let b = 0; b < nb; b++) {
    const a = rng() * Math.PI * 2;
    const bx = cx + Math.round(Math.cos(a) * 1.5);
    const bz = cz + Math.round(Math.sin(a) * 1.5);
    const by = Math.floor(th * (0.6 + rng() * 0.3));
    voxel(bx, by, bz, C.bark[0], { sy: 1.2 });
    tips.push([bx, by + 1, bz]);
  }
  // canopy clusters on tips + top
  for (const [tx, ty, tz] of tips) canopyEllipsoid(tx, ty + 1.2 * scale, tz, (1.6 + rng() * 0.7) * scale, (1.1 + rng() * 0.4) * scale, rng);
}
```
canopyEllipsoid: lattice dx in -rx..rx etc with1 steps, if (dx/rx)²+(dy/ry)²+(dz/rx)² <= 1 + (hash-0.5)*0.4 → voxel pink shade. Scale via rx float fine.

Note voxel positions with floats fine (voxel centers can be non-integer for organic look).

Pine:

```js
function pine(cx, cz, seed) {
  const rng = mulberry32(seed);
  const th = 4 + Math.floor(rng() * 2);
  for (let i = 0; i < th + 2; i++) voxel(cx, i + 0.5, cz, C.bark[1], { sx: i < th ? 0.7 : 0.5, sz: i < th ? 0.7 : 0.5 });
  let r = 2.4;
  for (let layer = 0; layer < 4; layer++) {
    const y = th - 0.5 + layer * 1.0;
    const rad = r * (1 - layer * 0.22);
    for (let dx = -Math.ceil(rad); dx <= Math.ceil(rad); dx++)
      for (let dz = -Math.ceil(rad); dz <= Math.ceil(rad); dz++) {
        const d = Math.hypot(dx, dz);
        if (d <= rad * (0.85 + 0.3 * hash2(dx + seed, dz - seed))) voxel(cx + dx, y, cz + dz, C.pine[layer % 3]);
      }
  }
  voxel(cx, th + 3.5, cz, C.pine[1], { sx: 0.6, sy: 1.2, sz: 0.6 });
}
```

