function bridge(zStart, zEnd, x) {
  const n = 14;
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    const z = zStart + (zEnd - zStart) * t;
    const y = 0.3 + Math.sin(Math.PI * t) * 1.15;
    voxel(x, y, z, C.wood, { sx: 1.7, sy: 0.28, sz: 0.38, ry: 0 });
    if (i % 2 === 0) {
      for (const s of [-1, 1]) {
        voxel(x + s * 0.95, y + 0.55, z, C.verm, { sx: 0.22, sy: 0.9, sz: 0.22 });
      }
    }
    for (const s of [-1, 1]) voxel(x + s * 0.95, y + 0.98, z, C.verm, { sx: 0.2, sy: 0.16, sz: 0.4 });
  }
}
```
