function makeKoi(colors, seed) {
  const g = new THREE.Group();
  const mat = (c) => new THREE.MeshLambertMaterial({ color: c });
  const mesh = (w, h, d, c, x, y, z) => {
    const m = new THREE.Mesh(unitBox, mat(c));
    m.scale.set(w, h, d); m.position.set(x, y, z);
    m.castShadow = true;
    g.add(m); return m;
  };
  mesh(0.55, 0.4, 0.9, colors.body, 0, 0, 0);
  mesh(0.45, 0.35, 0.5, colors.head ?? colors.body, 0, -0.02, 0.65);
  mesh(0.4, 0.3, 0.45, colors.body, 0, 0, -0.6);
  const tail = new THREE.Group(); tail.position.set(0, 0, -0.82);
  const tf = new THREE.Mesh(unitBox, mat(colors.fin ?? colors.body));
  tf.scale.set(0.1, 0.5, 0.55); tf.position.set(0, 0, -0.28); tf.castShadow = true;
  tail.add(tf); g.add(tail);
  for (const s of [-1, 1]) {
    const f = new THREE.Mesh(unitBox, mat(colors.fin ?? colors.body));
    f.scale.set(0.35, 0.07, 0.3); f.position.set(s * 0.38, -0.05, 0.15); f.rotation.y = s * 0.5; f.castShadow = true;
    g.add(f);
  }
  // dorsal
  const d = new THREE.Mesh(unitBox, mat(colors.fin ?? colors.body));
  d.scale.set(0.08, 0.25, 0.55); d.position.set(0, 0.28, -0.05); d.castShadow = true; g.add(d);
  // patches
  for (let i = 0; i < (colors.patches?.length ?? 0); i++) {
    const p = colors.patches[i];
    const m = new THREE.Mesh(unitBox, mat(p.c));
    m.scale.set(p.sx, 0.12, p.sz); m.position.set(p.x, 0.2, p.z); g.add(m);
  }
  // eyes
  for (const s of [-1, 1]) {
    const e = new THREE.Mesh(unitBox, mat('#1a1a20'));
    e.scale.set(0.08, 0.08, 0.08); e.position.set(s * 0.22, 0.08, 0.86); g.add(e);
  }
  g.userData.tail = tail;
  return g;
}
```
