const KEYS = [ ... {t:0...}, ..., {t:24, same as 0} ];
function sampleKeys(t) {
  let i = 0;
  while (i < KEYS.length - 2 && t > KEYS[i + 1].t) i++;
  const a = KEYS[i], b = KEYS[i + 1];
  let u = (t - a.t) / (b.t - a.t); u = Math.min(1, Math.max(0, u));
