function makeCurve(seed) {
  const rng = mulberry32(seed);
  const pts = [];
  const a0 = rng() * Math.PI * 2;
  for (let i = 0; i < 8; i++) {
    let a = a0 + (i / 8) * Math.PI * 2 + (rng() - 0.5) * 0.45;
    let r = 0.32 + rng() * 0.36;
    let x = POND.cx + Math.cos(a) * r * POND.rx;
    let z = POND.cz + Math.sin(a) * r * POND.rz;
    for (let tries = 0; tries < 6; tries++) {
      const di = Math.hypot(x - ISLE.cx, z - ISLE.cz);
      const bridgeBad = Math.abs(x - 11) < 2.0 && z > 7.8;
      if (di > 3.4 && !bridgeBad) break;
      r *= 0.62; a += 0.7;
      x = POND.cx + Math.cos(a) * r * POND.rx;
      z = POND.cz + Math.sin(a) * r * POND.rz;
    }
    pts.push(new THREE.Vector3(x, -0.4, z));
  }
  return new THREE.CatmullRomCurve3(pts, true, 'catmullrom', 0.55);
}
```
