head -20 <(node .scratch/cdp.mjs "http://127.0.0.1:8123/.scratch/test.html" /tmp/ocb/task-1-voxel-zen-garden/mimo-v2.6-flash/.scratch/g4 2>/dev/null) ; node -e '
const { spawn } = require("node:child_process");
(async () => {
  const port = 9777;
  const chrome = spawn("chromium", ["--headless=new","--no-sandbox","--disable-gpu","--enable-unsafe-swiftshader","--no-proxy-server","--window-size=800,500",`--remote-debugging-port=${port}`,"about:blank"],{stdio:["ignore","ignore","ignore"]});
  const wait = ms => new Promise(r=>setTimeout(r,ms));
  let ver; for (let i=0;i<50;i++){ try { ver = await (await fetch(`http://127.0.0.1:${port}/json/version`)).json(); break; } catch { await wait(300);} }
  const ws = new WebSocket(ver.webSocketDebuggerUrl);
  await new Promise((res,rej)=>{ws.onopen=res;ws.onerror=rej;});
  let id=0; const pend=new Map(); const errs=[];
  ws.onmessage=e=>{const m=JSON.parse(e.data); if(m.id&&pend.has(m.id)){pend.get(m.id)(m.result);pend.delete(m.id);} else if(m.method==="Runtime.exceptionThrown") errs.push(JSON.stringify(m.params.exceptionDetails).slice(0,300)); else if(m.method==="Runtime.consoleAPICalled"&&m.params.type==="error") errs.push(JSON.stringify(m.params.args));};
  const send=(method,params={},sessionId)=>{const i=++id;ws.send(JSON.stringify({id:i,method,params,...(sessionId?{sessionId}:{})}));return new Promise(r=>pend.set(i,r));};
  const {targetId}=await send("Target.createTarget",{url:"about:blank"});
  const {sessionId}=await send("Target.attachToTarget",{targetId,flatten:true});
  await send("Runtime.enable",{},sessionId);
  await send("Page.enable",{},sessionId);
  await send("Page.navigate",{url:"http://127.0.0.1:8123/.scratch/test.html"},sessionId);
  await wait(5000);
  await send("Runtime.evaluate",{expression:"window.__garden.setAuto(true); window.__garden.setTime(5)"},sessionId);
  await wait(45000);
  const r=await send("Runtime.evaluate",{expression:"JSON.stringify({t:window.__garden.time(),s:window.__garden.state(),fps:document.title})",returnByValue:true},sessionId);
  console.log(JSON.stringify({after45s:r.result&&r.result.value, exceptions:errs.slice(0,5)}));
  ws.close(); chrome.kill("SIGKILL"); process.exit(0);
})().catch(e=>{console.error(e);process.exit(1);});
'

